function validate(input) {
  const [{ Signups = [], Confirmations = [] }] = input;
  const stamp = /^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}$/;
  const users = new Set(), requests = new Set();
  for (const [id, time] of Signups) {
    if (id === null) return 'Every sign-up needs a user_id.';
    if (users.has(id)) return `user_id ${id} signs up twice.`;
    if (time === null || !stamp.test(time)) return `User ${id} needs a time_stamp like 2021-01-31 10:00:00.`;
    users.add(id);
  }
  for (const [id, time, action] of Confirmations) {
    if (!users.has(id)) return `Confirmation for user ${id}, who never signed up.`;
    if (time === null || !stamp.test(time)) return `A confirmation of user ${id} needs a time_stamp like 2021-01-31 10:00:00.`;
    if (action !== 'confirmed' && action !== 'timeout') return `action must be 'confirmed' or 'timeout', not ${action}.`;
    const key = `${id}|${time}`;
    if (requests.has(key)) return `User ${id} has two confirmations at ${time}.`;
    requests.add(key);
  }
  return null;
}

generator:
function generate(rand, size) {
  const small = size === 'small';
  const pick = n => Math.floor(rand() * n);
  const two = n => String(n).padStart(2, '0');
  // Small cases draw times from a tiny pool so different users share a time_stamp; each user still has distinct times.
  const stamp = year => small
    ? `${year}-0${1 + pick(3)}-01 ${two(9 + pick(3))}:00:00`
    : `${year}-${two(1 + pick(12))}-${two(1 + pick(28))} ${two(pick(24))}:${two(pick(60))}:${two(pick(60))}`;
  const users = small ? pick(6) : 1000;
  const Signups = [], Confirmations = [];
  let budget = small ? 8 : 2000;
  for (let id = 1; Signups.length < users; id++) {
    if (rand() < 0.3) continue;
    Signups.push([id, stamp(2020)]);
    // Each user leans towards confirming or not; at most 7 requests keeps every rate's rounding unambiguous.
    const lean = [0, 0.3, 0.5, 0.7, 1][pick(5)];
    const wanted = Math.min(budget, small ? pick(4) : pick(5));
    const times = new Set();
    for (let k = 0; k < wanted * 3 && times.size < wanted; k++) times.add(stamp(2021));
    for (const time of times) Confirmations.push([id, time, rand() < lean ? 'confirmed' : 'timeout']);
    budget -= times.size;
  }
  // Shuffle so rows of one user are not adjacent.
  for (let i = Confirmations.length - 1; i > 0; i--) { const j = pick(i + 1); [Confirmations[i], Confirmations[j]] = [Confirmations[j], Confirmations[i]]; }
  return [{ Signups, Confirmations }];
}
